"const sql = require('mssql');
require('dotenv').config({ path: '../backend/.env' });

const dbConfig = {
  server: process.env.DB_SERVER || 'localhost',
  database: process.env.DB_DATABASE || 'ControlabIA',
  user: process.env.DB_USER || 'controlab_user',
  password: process.env.DB_PASSWORD || 'Delicia1.',
  port: parseInt(process.env.DB_PORT) || 1433,
  options: {
    encrypt: false,
    trustServerCertificate: true,
    enableArithAbort: true
  }
};

async function run() {
  try {
    const pool = await sql.connect(dbConfig);
    console.log('Connected to DB!');

    // Check if log_process_automatico exists and has rows
    try {
      const res = await pool.request().query('SELECT TOP 5 * FROM log_process_automatico');
      console.log('log_process_automatico contents:', res.recordset);
    } catch (e) {
      console.log('Error querying log_process_automatico:', e.message);
    }

    // Check if log_proceso_automatico exists and has rows
    try {
      const res = await pool.request().query('SELECT TOP 5 * FROM log_proceso_automatico');
      console.log('log_proceso_automatico contents:', res.recordset);
    } catch (e) {
      console.log('Error querying log_proceso_automatico:', e.message);
    }

    // Check tables columns
    const columns = await pool.request().query(`
      SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE
      FROM INFORMATION_SCHEMA.COLUMNS
      WHERE TABLE_NAME IN ('log_proceso_automatico', 'log_process_automatico')
    `);
    console.log('Columns:');
    columns.recordset.forEach(c => console.log(` - ${c.TABLE_NAME}.${c.COLUMN_NAME} (${c.DATA_TYPE})`));

    await pool.close();
  } catch (err) {
    console.error(err);
  }
}

run();
"

