"const sql = require('mssql');
require('dotenv').config();

const dbConfig = {
  server: process.env.DB_SERVER || 'localhost',
  database: process.env.DB_DATABASE || 'ControlabIA',
  user: process.env.DB_USER || 'controlab_user',
  password: process.env.DB_PASSWORD || 'Delicia1.',
  port: parseInt(process.env.DB_PORT) || 1433,
  options: {
    encrypt: false,
    trustServerCertificate: true,
    enableArithAbort: true
  }
};

async function run() {
  try {
    const pool = await sql.connect(dbConfig);
    console.log('Connected to DB!');

    // Get stored procedure SP_EjecutarDescuentosMasivos definition
    try {
      const res = await pool.request().query("SELECT definition FROM sys.all_sql_modules WHERE object_id = OBJECT_ID('SP_EjecutarDescuentosMasivos')");
      if (res.recordset.length > 0) {
        console.log('SP_EjecutarDescuentosMasivos definition:');
        console.log(res.recordset[0].definition);
      } else {
        console.log('SP_EjecutarDescuentosMasivos not found in sys.all_sql_modules');
      }
    } catch (e) {
      console.log('Error getting definition:', e.message);
    }

    // List all stored procedures
    try {
      const res = await pool.request().query("SELECT name FROM sys.procedures");
      console.log('Stored procedures:');
      res.recordset.forEach(p => console.log(' - ' + p.name));
    } catch (e) {
      console.log('Error listing procedures:', e.message);
    }

    await pool.close();
  } catch (err) {
    console.error(err);
  }
}

run();
"

